/* 步骤 8：纯键盘操作（CDP Input 域 = 真实浏览器输入）：Tab 移动焦点至"投影:语言"，Enter 激活 */
async function pressKey(k) {
  await send('Input.dispatchKeyEvent', { type: 'rawKeyDown', key: k.key, code: k.code, windowsVirtualKeyCode: k.vk, nativeVirtualKeyCode: k.vk }, sessionId);
  await send('Input.dispatchKeyEvent', { type: 'keyUp', key: k.key, code: k.code, windowsVirtualKeyCode: k.vk, nativeVirtualKeyCode: k.vk }, sessionId);
}
await step(8, 'keyboard', async () => {
  let hit = false;
  for (let i = 0; i < 14; i++) {
    await pressKey({ key: 'Tab', code: 'Tab', vk: 9 });
    await sleep(60);
    const ae = await evaluate(`(() => { const el = document.activeElement; return el ? el.getAttribute('data-act') + ':' + (el.getAttribute('data-dim') || '') + ':' + getComputedStyle(el).outlineStyle : 'none'; })()`);
    if (ae === 'proj:language:solid') { hit = true; break; }
  }
  if (!hit) throw new Error('Tab 未到达 投影:语言 按钮（activeElement 未命中且 outline 非 solid）');
  await pressKey({ key: 'Enter', code: 'Enter', vk: 13 });
  await sleep(350);
}, () => evaluate(`(() => {
  const el = document.activeElement;
  return {
    chartTitle: document.querySelector('#chart-title').innerText.replace(/\\s+/g,' '),
    activeIsProjLanguage: el.matches('button[data-act="proj"][data-dim="language"]'),
    focusOutline: getComputedStyle(el).outlineStyle + ' ' + getComputedStyle(el).outlineWidth,
    trailCount: document.querySelectorAll('.trail-step').length
  };
})()`));

