```js
function focusKey(el){
  if(!el || !el.getAttribute) return null;
  const act = el.getAttribute('data-act'), dim = el.getAttribute('data-dim'), val = el.getAttribute('data-val'), id = el.id;
  if(id) return '#'+id;
  if(act && dim) return `[data-act="${act}"][data-dim="${dim}"]`;
  if(act && val) return `[data-act="${act}"][data-val="${val}"]`;
