.badge.stage-成熟 { background: #e6f6ec; border-color: #9fd8b4; color: #1b6e3d; }
.badge.stage-成长 { background: #fff4dc; border-color: #ecd39b; color: #8a5a00; }
.badge.stage-孵化 { background: #eef1f5; border-color: #c3ccd6; color: #57626f; }
.insp-dl { margin: 12px 0 0; width: 100%; border-collapse: collapse; }
.insp-dl th, .insp-dl td {
  text-align: left; padding: 3.5px 6px; border-bottom: 1px solid #eef1f5;
  font-size: 12px; font-weight: 400; vertical-align: middle;
}
.insp-dl th { color: var(--muted); width: 84px; }
.insp-dl td.v { text-align: right; font-variant-numeric: tabular-nums; }
.insp-dl tr.hot th, .insp-dl tr.hot td { background: var(--accent-soft); }
.insp-dl tr.hot th { color: var(--accent); font-weight: 650; }
.insp-pct { color: var(--faint); font-size: 10.5px; margin-left: 6px; }
.insp-tip { margin-top: 12px; color: var(--faint); font-size: 11px; line-height: 1.6; border-top: 1px dashed var(--border); padding-top: 8px; }

/* ---------- 状态条 ---------- */
#state-bar {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 10px; align-items: start;
  margin: 0 8px 8px;
  padding: 8px 12px;
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
}
.chips-line { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; min-height: 24px; }
