.chip .x:hover { color: var(--danger); }
.chip.ghost { border-style: dashed; color: var(--faint); background: transparent; }
.bar-side { display: flex; flex-direction: column; gap: 5px; align-items: flex-end; }
.bar-actions { display: flex; gap: 6px; }
.act-btn {
  display: inline-flex; align-items: center; gap: 5px;
  border: 1px solid var(--border); background: var(--panel);
  border-radius: 5px; padding: 3px 10px; cursor: pointer; font-size: 12px;
