const wsUrl = await new Promise((res, rej) => { let b = ''; const t = setTimeout(() => rej(new Error('timeout')), 15000); chrome.stderr.on('data', d => { b += d; const m = b.match(/DevTools listening on (ws:\/\/\S+)/); if (m) { clearTimeout(t); res(m[1]); } }); });
