const out = await q(`(() => {
  const bad = [];
  document.querySelectorAll('*').forEach(el => {
    const sw = el.scrollWidth, cw = el.clientWidth, sh = el.scrollHeight, ch = el.clientHeight;
    if (sw > cw + 1 || sh > ch + 1) {
      bad.push({
        tag: el.tagName, id: el.id || null, cls: (el.className && el.className.baseVal !== undefined ? el.className.baseVal : el.className || null).toString().slice(0, 40),
        sw, cw, sh, ch,
        text: (el.textContent || '').trim().slice(0, 24)
      });
    }
  });
  return bad.slice(0, 40);
})()`);
console.log(JSON.stringify(out, null, 2));
ws.close(); chrome.kill(); process.exit(0);

