#inspector .insp-head .sub { color: var(--faint); font-size: 11px; }
#insp-body { overflow-y: auto; padding: 10px 12px; }
.insp-empty { color: var(--faint); font-size: 12px; line-height: 1.6; }
.insp-name { font-size: 15px; font-weight: 650; display: flex; align-items: center; gap: 8px; }
.insp-id { color: var(--faint); font-family: var(--mono); font-size: 11px; }
.badge {
